MATCH (source:PlantItem {tag: 'P-5601C'}), (target:PlantItem {tag: 'R-5801'})
RETURN source.tag AS sourceTag,
       target.tag AS targetTag,
       EXISTS {
         MATCH (source)-[:send_to*1..]->(target)
       } AS canReach

MATCH (s:PlantItem {tag: 'F-701A'}), (t:PlantItem {tag: 'V-801'})
RETURN s.tag AS source_tag, t.tag AS target_tag,
       EXISTS {
         MATCH p = (s)-[:send_to*1..]->(t)
         WHERE ALL(n IN nodes(p) WHERE n.tag IS NULL OR n.tag <> 'XV-8028')
       } AS can_flow

